import Vue from 'vue'
import VueRouter from 'vue-router'
import MainLayout from '../layouts/MainLayout.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    component: MainLayout,
    redirect: '/dashboard',
    children: [
      {
        path: 'dashboard',
        name: 'Dashboard',
        component: () => import('../views/Dashboard.vue'),
        meta: { title: '仪表盘' }
      },
      {
        path: 'servers',
        name: 'Servers',
        redirect: '/servers/list',
        children: [
          {
            path: 'list',
            name: 'ServerList',
            component: () => import('../views/servers/ServerList.vue'),
            meta: { title: '服务器列表' }
          },
          {
            path: 'settings',
            name: 'ServerSettings',
            component: () => import('../views/servers/ServerSettings.vue'),
            meta: { title: '服务器设置' }
          }
        ]
      },
      {
        path: 'players',
        name: 'Players',
        redirect: '/players/list',
        children: [
          {
            path: 'list',
            name: 'PlayerList',
            component: () => import('../views/players/PlayerList.vue'),
            meta: { title: '玩家列表' }
          },
          {
            path: 'ban',
            name: 'BanList',
            component: () => import('../views/players/BanList.vue'),
            meta: { title: '封禁管理' }
          }
        ]
      },
      {
        path: 'items',
        name: 'Items',
        redirect: '/items/list',
        children: [
          {
            path: 'list',
            name: 'ItemList',
            component: () => import('../views/items/ItemList.vue'),
            meta: { title: '物品列表' }
          },
          {
            path: 'generator',
            name: 'ItemGenerator',
            component: () => import('../views/items/ItemGenerator.vue'),
            meta: { title: '物品生成器' }
          }
        ]
      },
      {
        path: 'mods',
        name: 'Mods',
        redirect: '/mods/list',
        children: [
          {
            path: 'list',
            name: 'ModList',
            component: () => import('../views/mods/ModList.vue'),
            meta: { title: '模组列表' }
          },
          {
            path: 'settings',
            name: 'ModSettings',
            component: () => import('../views/mods/ModSettings.vue'),
            meta: { title: '模组配置' }
          }
        ]
      },
      {
        path: 'backups',
        name: 'Backups',
        component: () => import('../views/Backups.vue'),
        meta: { title: '备份管理' }
      },
      {
        path: 'system',
        name: 'System',
        component: () => import('../views/System.vue'),
        meta: { title: '系统设置' }
      }
    ]
  },
  {
    path: '/login',
    name: 'Login',
    component: () => import('../views/Login.vue')
  },
  {
    path: '*',
    redirect: '/'
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

router.beforeEach((to, from, next) => {
  document.title = `饥荒管理系统 - ${to.meta.title || ''}`
  next()
})

export default router
